{
  "summary": "Overall the app uses the theme tokens for colors, spacing, radii and typography, and the main navigation structure matches the design. However critical issues prevent the primary flow from working and several required states and accessibility best‑practices are missing. The Sign‑Up (and likely Sign‑In) email fields are not identifiable by screen‑readers or test automation, breaking account creation. Dashboard, Receipt Capture, Mileage Entry and Export screens lack the error/offline banners, loading overlays, and field‑level validation UI specified in DESIGN.md. Accessible landmarks (SafeAreaView), focus rings for web, password‑show toggle, live password rule list and inline error messages are also absent or incomplete.",
  "findings": [
    {
      "severity": "high",
      "file": "expo-app/src/screens/SignUpScreen.tsx",
      "issue": "The email TextInput has no visible label or accessibilityLabel/testID, so automated tests cannot locate it and screen readers cannot announce it. The field is also missing nativeID linking for the label.",
      "fix": "Add a <Text> label \"Email address\" above the TextInput, give the TextInput a nativeID (e.g., nativeID=\"emailInput\"), set accessibilityLabel=\"Email address\", and add testID=\"emailInput\". Ensure autoCapitalize=\"none\" and keyboardType=\"email-address\" are set."
    },
    {
      "severity": "high",
      "file": "expo-app/src/screens/SignInScreen.tsx",
      "issue": "The email TextInput suffers from the same accessibility/labeling issue as Sign‑Up, causing the login flow to be inaccessible to screen readers and automated tests.",
      "fix": "Apply the same labeling strategy as in Sign‑Up: visible <Text> label, nativeID, accessibilityLabel, and testID for the email input."
    },
    {
      "severity": "medium",
      "file": "expo-app/src/screens/SignUpScreen.tsx",
      "issue": "No loading overlay is shown while the account is being created; the design requires a full‑screen spinner with the message \"Creating account…\" and fields disabled.",
      "fix": "Wrap the submit action in state, render <LoadingOverlay message=\"Creating account…\" /> when loading, and disable inputs/buttons during this state."
    },
    {
      "severity": "medium",
      "file": "expo-app/src/screens/SignUpScreen.tsx",
      "issue": "Field‑level validation errors are not displayed inline under the inputs; the design mandates specific inline messages for invalid email and password rules.",
      "fix": "Validate inputs on blur/submit, store error messages in state, and render a <Text style={errorStyle}> error message </Text> directly beneath each problematic field using the theme's error colors."
    },
    {
      "severity": "medium",
      "file": "expo-app/src/screens/SignUpScreen.tsx",
      "issue": "Password field does not include a trailing eye‑icon to toggle visibility and lacks an accessible \"Show password\" label.",
      "fix": "Add an eye‑icon button inside the TextInput (using absolute positioning) that toggles secureTextEntry, and give it accessibilityLabel=\"Show password\" (or \"Hide password\" when visible)."
    },
    {
      "severity": "medium",
      "file": "expo-app/src/screens/SignUpScreen.tsx",
      "issue": "Live password rule list (\"12 + characters, uppercase, lowercase, number, symbol\") is not displayed, violating the spec’s real‑time feedback requirement.",
      "fix": "Render a <Text> below the password field that updates in real‑time based on password validation, using theme.typography.caption styling."
    },
    {
      "severity": "medium",
      "file": "expo-app/src/screens/SignInScreen.tsx",
      "issue": "Missing loading overlay and field‑level error UI for login failures (e.g., \"Incorrect email or password.\") as defined in the spec.",
      "fix": "Add <LoadingOverlay message=\"Signing you in…\" /> during login request, disable fields, and display top toast with the exact error message on failure."
    },
    {
      "severity": "medium",
      "file": "expo-app/src/screens/DashboardScreen.tsx",
      "issue": "API error and offline banners defined in the spec are not implemented; the screen only shows a spinner or the data.",
      "fix": "Add a banner component at the top of the ScrollView that appears when fetch fails (showing \"Failed to load data. Pull down to retry.\") or when navigator.isOnline is false (showing \"You’re offline – data may be outdated.\")."
    },
    {
      "severity": "medium",
      "file": "expo-app/src/screens/DashboardScreen.tsx",
      "issue": "The screen does not use a SafeAreaView with accessibilityRole=\"main\"; design calls for a SafeAreaView landmark for proper inset handling and accessibility.",
      "fix": "Wrap the top‑level ScrollView in <SafeAreaView style={{flex:1}} accessibilityRole=\"main\"> ... </SafeAreaView>."
    },
    {
      "severity": "medium",
      "file": "expo-app/src/components/PrimaryButton.tsx",
      "issue": "No visible focus indicator for keyboard/web navigation; design requires a 2 px solid primary focus ring.",
      "fix": "Add a focused style using the `focused` state from Pressable (or onFocus/onBlur) that sets borderWidth: 2 and borderColor: theme.colors.primary."
    },
    {
      "severity": "medium",
      "file": "expo-app/src/components/PrimaryButton.tsx",
      "issue": "Missing `accessibilityHint` describing the button’s action (e.g., \"Adds a new receipt\") which helps screen readers.",
      "fix": "Pass an optional `accessibilityHint` prop and set it on the Pressable (e.g., accessibilityHint=\"Adds a new receipt\")."
    },
    {
      "severity": "low",
      "file": "expo-app/src/components/Header.tsx",
      "issue": "Header does not account for the device status‑bar safe‑area inset on iOS/Android, potentially cropping the title.",
      "fix": "Wrap Header in <SafeAreaView edges={['top']} /> or add paddingTop: Platform.OS === 'ios' ? 44 : 0 using theme.spacing."
    },
    {
      "severity": "low",
      "file": "expo-app/src/components/LoadingOverlay.tsx",
      "issue": "Overlay background color is hard‑coded as 'rgba(0,0,0,0.3)' instead of using a theme token (e.g., a disabledBackground with opacity).",
      "fix": "Replace the hard‑coded value with a token from theme (e.g., `${theme.colors.disabledBackground}80`)."
    },
    {
      "severity": "low",
      "file": "expo-app/src/screens/ReceiptCaptureScreen.tsx",
      "issue": "Permission prompt UI is not implemented as a modal using the custom Modal component defined in the design; fallback UI may not match token styles.",
      "fix": "Use the shared Modal component with title \"Camera access needed\", body text from spec, and actions styled with primary / accent buttons."
    },
    {
      "severity": "low",
      "file": "expo-app/src/screens/MileageEntryScreen.tsx",
      "issue": "No explicit use of the themed TextInput component; plain RN TextInput will not apply the surface background, border colors, and focus styles defined in the design tokens.",
      "fix": "Create a reusable <ThemedTextInput> component that applies theme.colors.surface, borderRadius, padding, and state‑based border colors (primary on focus, error on validation)."
    },
    {
      "severity": "low",
      "file": "expo-app/src/screens/ExportScreen.tsx",
      "issue": "Export buttons are rendered without disabling them and showing a spinner during generation, as required for the loading CSV/PDF states.",
      "fix": "Wrap the Export CSV and Export PDF buttons in state; when generating, set disabled={true} and replace label with <ActivityIndicator/> while showing the appropriate message (\"Generating CSV…\" or \"Generating PDF…\")."
    }
  ]
}

