        accessibilityLabel="Log in"
        testID="back-to-signin"
      >
        <Text style={styles.linkText}>Already have an account? Log in</Text>
      </TouchableOpacity>
      {loading && <LoadingOverlay message="Creating account…" />}
    </View>
  );
